const allowed = ['success', 'validation_fail', 'wrong_key'];
const scenario = allowed.includes(($json.test_scenario || '').trim()) ? ($json.test_scenario || '').trim() : 'success';

let question = ($json.success_question || '').trim();
let gatewayKey = ($json.real_gateway_key || '').trim();
let expectedBranch = 'success';
let expectedStatus = 'completed';
let expectedGatewayCall = true;
let notes = 'Expected Gateway success path';

if (scenario === 'validation_fail') {
  question = '';
  gatewayKey = ($json.real_gateway_key || '').trim();
  expectedBranch = 'validation_fail';
  expectedStatus = 'validation_failed';
  expectedGatewayCall = false;
  notes = 'Should fail in n8n validation before HTTP request';
} else if (scenario === 'wrong_key') {
  question = ($json.wrong_key_question || 'ทดสอบ wrong key').trim();
  gatewayKey = ($json.wrong_gateway_key || 'WRONG_KEY_FOR_TEST').trim();
  expectedBranch = 'gateway_failure';
  expectedStatus = 'gateway_failed';
  expectedGatewayCall = true;
  notes = 'Should reach Gateway but fail auth';
}

return [{
  json: {
    test_scenario: scenario,
    gateway_url: ($json.gateway_url || '').trim(),
    gateway_key: gatewayKey,
    mode: ($json.mode || 'answer').trim(),
    task_type: ($json.task_type || 'project_qa').trim(),
    actor_id: ($json.actor_id || 'n8n-manual-pilot').trim(),
    question,
    project_code: ($json.project_code || '').trim(),
    workflow_code: ($json.workflow_code || '').trim(),
    doc_scope: ($json.doc_scope || 'registry').trim(),
    trace_prefix: ($json.trace_prefix || 'qa').trim(),
    include_context: Boolean($json.include_context),
    temperature: Number($json.temperature ?? 0.2),
    max_output_tokens: Number($json.max_output_tokens ?? 1200),
    expected: {
      branch: expectedBranch,
      status: expectedStatus,
      should_call_gateway: expectedGatewayCall,
      notes
    }
  }
}];

const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const stamp = `${now.getFullYear()}${pad(now.getMonth()+1)}${pad(now.getDate())}-${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;
const rand = Math.random().toString(36).slice(2, 8);

const question = ($json.question || '').trim();
const gatewayUrl = ($json.gateway_url || '').trim().replace(/\/$/, '');
const gatewayKey = ($json.gateway_key || '').trim();
const mode = ($json.mode || '').trim();
const taskType = ($json.task_type || '').trim();
const tracePrefix = ($json.trace_prefix || 'qa').trim();
const actorId = ($json.actor_id || 'n8n-manual-pilot').trim();
const projectCode = ($json.project_code || '').trim();
const workflowCode = ($json.workflow_code || '').trim();
const docScope = ($json.doc_scope || 'registry').trim();
const includeContext = Boolean($json.include_context);
const temperature = Number($json.temperature ?? 0.2);
const maxOutputTokens = Number($json.max_output_tokens ?? 1200);

const errors = [];

if (!gatewayUrl) errors.push('gateway_url is required');
if (!gatewayKey) errors.push('gateway_key is required');
if (!question) errors.push('question is required');
if (!taskType) errors.push('task_type is required');
if (!['idea', 'answer', 'build'].includes(mode)) errors.push('mode must be one of idea|answer|build');
if (taskType !== 'project_qa') errors.push('task_type must be project_qa for this pilot');

const traceId = `${tracePrefix}_${stamp}_${rand}`;

const requestPayload = {
  trace_id: traceId,
  mode,
  task_type: taskType,
  actor: {
    type: 'system',
    id: actorId
  },
  input: {
    question
  },
  context: {
    include_context: includeContext,
    registry: {
      project_codes: projectCode ? [projectCode] : [],
      workflow_codes: workflowCode ? [workflowCode] : [],
      doc_scope: docScope
    }
  },
  options: {
    temperature,
    max_output_tokens: maxOutputTokens
  },
  metadata: {
    source: 'n8n',
    workflow_name: 'AI Gateway - Project QA Test Harness',
    workflow_version: 'v1.1-test-harness',
    manual_trigger: true,
    test_scenario: $json.test_scenario || 'success',
    expected: $json.expected || {}
  }
};

return [{
  json: {
    ...$json,
    trace_id: traceId,
    validation: {
      ok: errors.length === 0,
      errors
    },
    request_payload: requestPayload
  }
}];

return [{
  json: {
    ok: false,
    status: 'validation_failed',
    is_retriable: false,
    failure_stage: 'validation',
    trace_id: $json.trace_id,
    test_scenario: $json.test_scenario || null,
    expected: $json.expected || {},
    task_type: $json.task_type,
    mode: $json.mode,
    input_question: $json.question,
    errors: $json.validation.errors,
    request_preview: $json.request_payload
  }
}];

const result = $json.result || $json.output || {};
const answer = result.answer || result.final_answer || result.text || null;
const citations = result.citations || [];

return [{
  json: {
    ok: true,
    status: 'completed',
    is_retriable: false,
    failure_stage: null,
    trace_id: $json.trace_id || null,
    run_id: $json.run_id || null,
    provider: $json.provider || null,
    model: $json.model || null,
    mode: $json.mode || 'answer',
    task_type: $json.task_type || 'project_qa',
    answer,
    citations,
    raw_result: result,
    gateway_response: $json
  }
}];

const err = $json.error || {};
const message = err.message || $json.message || 'Gateway request failed';

return [{
  json: {
    ok: false,
    status: 'gateway_failed',
    is_retriable: typeof $json.is_retriable === 'boolean' ? $json.is_retriable : true,
    failure_stage: $json.failure_stage || err.stage || 'execution',
    trace_id: $json.trace_id || null,
    task_type: $json.task_type || 'project_qa',
    mode: $json.mode || 'answer',
    error_message: message,
    error_detail: err,
    gateway_response: $json
  }
}];
